/** Startup schema validation must admit recovery without trusting the incomplete native metadata base. */
class LmdbMetadataManifestAdmissionTest {

	private static final byte[] MANIFEST_KEY = "\u0000rdf4j-adjacency-metadata-checkpoint-v1"
			.getBytes(StandardCharsets.UTF_8);
	private static final byte[] TOTAL_KEY = { 1, 0 };
	@TempDir
	Path directory;

	@ParameterizedTest
	@ValueSource(strings = { "missing", "dirty", "malformed", "mismatched" })
	void discoveryDefersMalformedCoveredCountUntilRawRecovery(String manifest) throws Exception {
		createRepository();
		transact(true, (stack, txn) -> {
			int namespaces = LmdbUtil.openDatabaseWithTxn(txn, TripleStore.NAMESPACE_DATABASE_NAME, 0);
			int metadata = LmdbPersistentAdjacency.openExisting(txn).metadataDbi();
			put(stack, txn, metadata, TOTAL_KEY, new byte[] { 42 });
			if (manifest.equals("missing")) {
				int result = mdb_del(txn, namespaces, MDBVal.malloc(stack).mv_data(stack.bytes(MANIFEST_KEY)), null);
				if (result != MDB_NOTFOUND) {
					E(result);
				}
			} else {
				put(stack, txn, namespaces, MANIFEST_KEY, switch (manifest) {
				case "dirty" -> manifest(txn, false, false);
				case "mismatched" -> manifest(txn, true, true);
				default -> new byte[] { 42 };
				});
			}
			return null;
		});
		assertThatCode(() -> LegacyStoreDiscovery.discover(directory.toFile(), properties()))
				.doesNotThrowAnyException();
		transact(false, (stack, txn) -> {
			MDBVal value = MDBVal.malloc(stack);
			E(mdb_get(txn, LmdbPersistentAdjacency.openExisting(txn).metadataDbi(),
					MDBVal.malloc(stack).mv_data(stack.bytes(TOTAL_KEY)), value));
			assertThat(value.mv_size()).as("discovery is read-only; recovery owns the later replacement").isEqualTo(1);
			assertThat(value.mv_data().get(0)).isEqualTo((byte) 42);
			return null;
		});
		LmdbStore reopened = new LmdbStore(directory.toFile(), config());
		reopened.init();
		try (var connection = reopened.getConnection()) {
			assertThat(connection.size()).as("startup reconstructs counts before admitting queries").isEqualTo(1);
			try (var statements = connection.getStatements(null, null, null, false)) {
				assertThat(statements.hasNext()).isTrue();
				assertThat(statements.next().getSubject().stringValue()).isEqualTo("urn:checkpoint:subject");
				assertThat(statements.hasNext()).isFalse();
			}
		} finally {
			reopened.shutDown();
		}
		transact(false, (stack, txn) -> {
			int namespaces = LmdbUtil.openDatabaseWithTxn(txn, TripleStore.NAMESPACE_DATABASE_NAME, 0);
			assertThat(LmdbMetadataCheckpoint.inspect(txn, namespaces).clean()).isTrue();
			assertThat(LmdbPersistentAdjacency.openExisting(txn).count(txn, true)).isEqualTo(1);
			return null;
		});
	}

	@Test
	void matchingCleanManifestDoesNotExcuseMalformedCoveredCounts() throws Exception {
		createRepository();
		transact(true, (stack, txn) -> {
			put(stack, txn, LmdbPersistentAdjacency.openExisting(txn).metadataDbi(), TOTAL_KEY, new byte[] { 42 });
			put(stack, txn, LmdbUtil.openDatabaseWithTxn(txn, TripleStore.NAMESPACE_DATABASE_NAME, 0), MANIFEST_KEY,
					manifest(txn, true, false));
			return null;
		});
		assertThatThrownBy(() -> LegacyStoreDiscovery.discover(directory.toFile(), properties()))
				.isInstanceOf(IOException.class)
				.hasMessageContaining("count length");
	}

	@Test
	void recoveryNeededDoesNotAdmitUnrecognizedNamespaceKeys() throws Exception {
		createRepository();
		transact(true, (stack, txn) -> {
			int namespaces = LmdbUtil.openDatabaseWithTxn(txn, TripleStore.NAMESPACE_DATABASE_NAME, 0);
			put(stack, txn, namespaces, MANIFEST_KEY, manifest(txn, false, false));
			put(stack, txn, namespaces, "unknown-checkpoint-key".getBytes(StandardCharsets.UTF_8), new byte[] { 1 });
			return null;
		});
		assertThatThrownBy(() -> LegacyStoreDiscovery.discover(directory.toFile(), properties()))
				.isInstanceOf(IOException.class)
				.hasMessageContaining("Unrecognized namespace");
	}

	@Test
	void cleanCloseManifestIsAdmittedByOrdinaryAndFastSchemaValidation() throws Exception {
		createRepository();
		StoreProperties properties = properties();
		assertThatCode(() -> LegacyStoreDiscovery.discover(directory.toFile(), properties)).doesNotThrowAnyException();
		transact("values", false, (valueStack, valuesTxn) -> transact(false, (stack, triplesTxn) -> {
			int counts = LmdbUtil.openDatabaseWithTxn(valuesTxn, "ref_counts", 0);
			assertThat(ValueStore.isValidRefCountMarker(
					ByteBuffer.wrap(read(stack, valuesTxn, counts, new byte[] { 0 })), mdb_txn_id(valuesTxn)))
							.as("paired dictionary close must remain certified after metadata checkpoint")
							.isTrue();
			int metadata = LmdbUtil.openDatabaseWithTxn(valuesTxn, "gc_meta", 0);
			assertThat(ByteBuffer.wrap(read(stack, valuesTxn, metadata,
					PreparedBulkStore.CLEAN_TRIPLE_TRANSACTION_KEY)).getLong())
							.as("dictionary close is bound to the final triple metadata transaction")
							.isEqualTo(mdb_txn_id(triplesTxn));
			LegacyStoreDiscovery.validateCurrentMetadata(stack, valuesTxn, triplesTxn, properties);
			return null;
		}));
		assertThat(PreparedBulkStore.readCurrent(directory, properties, config())).isNotNull();
	}

	private static byte[] manifest(long txn, boolean clean, boolean mismatched) {
		long id = mdb_txn_id(txn);
		return ByteBuffer.allocate(40)
				.putLong(0x524446344a4d4331L)
				.putInt(1)
				.putInt(0x7f)
				.putLong(clean ? id - (mismatched ? 1 : 0) : 0)
				.putLong(id)
				.putLong(clean ? 1 : 0)
				.array();
	}

	private StoreProperties properties() throws IOException {
		StoreProperties properties = new StoreProperties(directory.toFile());
		properties.load();
		return properties;
	}

	private void createRepository() {
		LmdbStore store = new LmdbStore(directory.toFile(), config());
		store.init();
		try (var connection = store.getConnection()) {
			var values = store.getValueFactory();
			connection.begin();
			// Native fast admission intentionally requires an initialized namespace snapshot, which is lazy.
			connection.setNamespace("checkpoint", "urn:checkpoint:");
			connection.addStatement(values.createIRI("urn:checkpoint:subject"),
					values.createIRI("urn:checkpoint:predicate"),
					values.createLiteral("object"));
			connection.commit();
		} finally {
			store.shutDown();
		}
	}

	private <T> T transact(boolean write, LmdbUtil.Transaction<T> action) throws IOException {
		return transact("triples", write, action);
	}

	private <T> T transact(String subdirectory, boolean write, LmdbUtil.Transaction<T> action) throws IOException {
		long environment = 0;
		try (MemoryStack stack = stackPush()) {
			PointerBuffer pointer = stack.mallocPointer(1);
			E(mdb_env_create(pointer));
			environment = pointer.get(0);
			E(mdb_env_set_maxdbs(environment, 128));
			E(mdb_env_open(environment, directory.resolve(subdirectory).toString(),
					MDB_NOTLS | (write ? 0 : MDB_RDONLY),
					0664));
			return write ? LmdbUtil.writeTransaction(environment, action)
					: LmdbUtil.readTransaction(environment, action);
		} finally {
			if (environment != 0) {
				mdb_env_close(environment);
			}
		}
	}

	private static byte[] read(MemoryStack stack, long txn, int database, byte[] key) throws IOException {
		MDBVal value = MDBVal.malloc(stack);
		E(mdb_get(txn, database, MDBVal.malloc(stack).mv_data(stack.bytes(key)), value));
		assertThat(value.mv_size()).isBetween(1L, 128L);
		byte[] bytes = new byte[(int) value.mv_size()];
		value.mv_data().get(bytes);
		return bytes;
	}

	private static void put(MemoryStack stack, long txn, int database, byte[] key, byte[] value) throws IOException {
		E(mdb_put(txn, database, MDBVal.malloc(stack).mv_data(stack.bytes(key)),
				MDBVal.malloc(stack).mv_data(stack.bytes(value)), 0));
	}

	private static LmdbStoreConfig config() {
		return new LmdbStoreConfig("spoc,posc").setForceSync(true).setInitialRunImportEnabled(false);
	}
}
